  KidsStory(id: 'musa', category: StoryCategory.prophets, seconds: 117.20, bytes: 11174773, captions: [
    StoryCaption(0.25, 9.12, text: 'أمرَ اللهُ نبيَّهُ موسى عليهِ السلامُ أن يخرجَ ليلًا بمَن آمنَ معهُ من بني إسرائيلَ.'),
    StoryCaption(9.67, 17.00, text: 'فلمّا علِمَ فرعونُ بخروجِهِم، أرسلَ جنودَهُ يجمعونَ جيشَهُ من كلِّ المدنِ.'),
    StoryCaption(17.55, 23.44, text: 'وقالَ فرعونُ: إنّهُم قليلونَ، ونحنُ مستعدّونَ لهُم.'),
