    StoryCaption(27.18, 33.80, text: 'ثمَّ دعا ربَّهُ: يا ربِّ، أصابَني التعبُ والألمُ، وأنتَ أرحمُ الراحمينَ.'),
    StoryCaption(34.35, 48.14, surah: 21, ayah: 83),
    StoryCaption(48.99, 53.77, text: 'فاستجابَ اللهُ دعاءَهُ، وقالَ لهُ: اضرِبِ الأرضَ برِجلِكَ.'),
    StoryCaption(54.32, 60.57, text: 'فنبعَ من الأرضِ ماءٌ باردٌ، فشرِبَ منهُ واغتسلَ، فذهبَ عنهُ المرضُ.'),
    StoryCaption(61.12, 66.33, text: 'وردَّ اللهُ عليهِ أهلَهُ، وأعطاهُ مثلَهُم معَهُم، رحمةً منهُ.'),
    StoryCaption(66.88, 73.58, text: 'وأثنى اللهُ عليهِ فقالَ: إنّا وجدناهُ صابرًا، نِعمَ العبدُ.'),
    StoryCaption(74.13, 79.64, text: 'وجعلَهُ اللهُ قُدوةً لكلِّ صابرٍ، يرجو رحمةَ ربِّهِ.'),
    StoryCaption(80.19, 88.71, text: 'تعلَّمْنا من أيّوبَ: أن نصبرَ إذا مرِضْنا أو حزِنّا، وأن ندعوَ اللهَ، فبعدَ الصبرِ يأتي الفرَجُ.'),
  ]),
  KidsStory(id: 'zakariya', category: StoryCategory.prophets, seconds: 127.80, bytes: 9275783, captions: [
    StoryCaption(0.25, 8.11, text: 'كانَ زكريّا عليهِ السلامُ نبيًّا صالحًا، يكفُلُ مريمَ، وأسكنَها في مكانِ عبادتِهِ.'),
    StoryCaption(8.66, 18.03, text: 'وكانَ كلَّما دخلَ عليها وجدَ عندَها رزقًا طيِّبًا، فيسألُها: من أينَ لكِ هذا؟ فتقولُ: هو من عندِ اللهِ.'),
    StoryCaption(18.58, 25.16, text: 'وكانَ زكريّا قد كبِرَ، وضعُفَ عظمُهُ، وابيضَّ شعرُ رأسِهِ، وامرأتُهُ لا تلِدُ.'),
    StoryCaption(25.71, 32.87, text: 'فلمّا رأى ما أكرمَ اللهُ بهِ مريمَ، دعا ربَّهُ سِرًّا أن يرزُقَهُ ولدًا صالحًا.'),
    StoryCaption(33.42, 47.76, surah: 21, ayah: 89),
    StoryCaption(48.61, 56.53, text: 'فبينما هو قائمٌ يصلّي في مِحرابِهِ، جاءَتْهُ البُشرى: سيُرزَقُ بولدٍ اسمُهُ يحيى.'),
    StoryCaption(57.08, 60.62, text: 'ولم يُسَمِّ اللهُ أحدًا قبلَهُ بهذا الاسمِ.'),
    StoryCaption(61.17, 66.95, text: 'فتعجَّبَ زكريّا فرِحًا: كيفَ يكونُ لي ولدٌ وقد كبِرتُ، وامرأتي لا تلِدُ؟'),
    StoryCaption(67.50, 73.42, text: 'فقيلَ لهُ: ذلكَ هيِّنٌ على اللهِ، فقد خلقَكَ من قبلُ ولم تكُنْ شيئًا.'),
    StoryCaption(73.97, 82.08, text: 'وكانَتْ علامتُهُ ألّا يقدِرَ على كلامِ الناسِ ثلاثةَ أيّامٍ، وهو صحيحٌ معافى.'),
    StoryCaption(82.63, 89.00, text: 'فخرجَ إلى قومِهِ، وأشارَ إليهِم: سبِّحوا اللهَ صباحًا ومساءً.'),
    StoryCaption(89.55, 99.35, text: 'فوُلِدَ يحيى، وأمرَهُ اللهُ وهو صغيرٌ أن يأخذَ التوراةَ بجِدٍّ، يحفظُها ويفهمُها ويعملُ بها.'),
    StoryCaption(99.90, 106.95, text: 'وأعطاهُ اللهُ الحكمةَ وهو صغيرٌ، وكانَ رحيمًا، مطيعًا لربِّهِ.'),
    StoryCaption(107.50, 115.46, text: 'وكانَ بارًّا بوالدَيْهِ، مطيعًا لهُما، ولم يكُنْ متكبِّرًا ولا عاصيًا.'),
    StoryCaption(116.01, 126.30, text: 'تعلَّمْنا من زكريّا ويحيى: أن ندعوَ اللهَ ولا نيأسَ أبدًا، وأن نكونَ بارّينَ بآبائِنا وأمهاتِنا.'),
  ]),
  KidsStory(id: 'kaaba', category: StoryCategory.prophets, seconds: 179.73, bytes: 12074260, captions: [
    StoryCaption(0.25, 8.60, text: 'أمرَ اللهُ إبراهيمَ عليهِ السلامُ، فأسكنَ ابنَهُ إسماعيلَ وأمَّهُ هاجَرَ في وادي مكّةَ.'),
    StoryCaption(9.15, 14.80, text: 'وكانَ وادِيًا ليسَ فيهِ زرعٌ ولا ماءٌ، بجِوارِ بيتِ اللهِ.'),
    StoryCaption(15.35, 23.55, text: 'ولمّا انصرفَ إبراهيمُ، قالَتْ لهُ هاجَرُ: آللهُ الذي أمرَكَ بهذا؟ قالَ: نعم. قالَتْ: إذًا لا يُضيِّعُنا.'),
    StoryCaption(24.10, 31.86, text: 'فدعا إبراهيمُ ربَّهُ: أن يجعلَ قلوبَ الناسِ تحِنُّ إليهِم، وأن يرزُقَهُم من الثمراتِ؛ ليشكُروا.'),
    StoryCaption(32.41, 42.52, text: 'ودعا أن تكونَ مكّةُ بلدًا آمِنًا، وأن يُبعِدَهُ اللهُ وأبناءَهُ عن عبادةِ الأصنامِ. فاستجابَ اللهُ دعاءَهُ.'),
    StoryCaption(43.07, 47.09, text: 'ولمّا فرغَ الماءُ، عطِشَتْ هاجَرُ وعطِشَ ابنُها.'),
    StoryCaption(47.64, 60.41, text: 'فصعِدَتْ جبلَ الصفا تنظُرُ هل ترى أحدًا، ثمَّ أتَتِ المروةَ، ففعلَتْ ذلكَ سبعَ مرّاتٍ. قالَ النبيُّ ﷺ: فذلكَ سعيُ الناسِ بينَهُما.'),
    StoryCaption(60.96, 66.85, text: 'فإذا هي بالمَلَكِ عندَ موضعِ زمزمَ، فبحثَ الأرضَ حتّى ظهرَ الماءُ.'),
    StoryCaption(67.40, 77.80, text: 'فشرِبَتْ وأرضعَتْ ولدَها، وقالَ لها المَلَكُ: لا تخافوا الضَّيعةَ؛ فإنَّ هاهنا بيتَ اللهِ، يبنيهِ هذا الغلامُ وأبوهُ.'),
    StoryCaption(78.35, 83.37, text: 'ثمَّ بيَّنَ اللهُ لإبراهيمَ مكانَ البيتِ، وأمرَهُ أن يبنيَهُ.'),
    StoryCaption(83.92, 92.71, text: 'فرفعَ إبراهيمُ وإسماعيلُ أُسُسَ الكعبةِ، حجرًا فوقَ حجرٍ، وهما يدعوانِ اللهَ في خشوعٍ.'),
    StoryCaption(93.26, 110.29, surah: 2, ayah: 127),
    StoryCaption(111.14, 118.80, text: 'ووقفَ إبراهيمُ على حجرٍ وهو يبني، وهو مقامُ إبراهيمَ الذي نصلّي عندَهُ.'),
    StoryCaption(119.35, 128.65, text: 'ودعَوا اللهَ: أن يجعلَهُما ثابتَيْنِ على الإسلامِ، وأن يجعلَ من ذرّيّتِهِما أمّةً مسلمةً.'),
    StoryCaption(129.20, 142.73, text: 'ودعَوا أن يبعثَ اللهُ في ذرّيّتِهِما رسولًا يُعلِّمُهُمُ القرآنَ؛ فكانَ نبيَّنا محمّدًا ﷺ، من ذرّيّةِ إسماعيلَ.'),
    StoryCaption(143.28, 148.99, text: 'وأمرَهُما اللهُ أن يُطهِّرا بيتَهُ للطائفينَ والمصلّينَ.'),
    StoryCaption(149.54, 158.80, text: 'ثمَّ أمرَهُ اللهُ أن ينادِيَ في الناسِ بالحجِّ، فيأتونَ ماشينَ وراكبينَ، من كلِّ طريقٍ بعيدٍ.'),
    StoryCaption(159.35, 166.46, text: 'وجعلَ اللهُ الكعبةَ مكانًا يرجِعُ إليهِ الناسُ، وأمنًا لهُم.'),
    StoryCaption(167.01, 178.23, text: 'تعلَّمْنا من إبراهيمَ وإسماعيلَ: أن نُطيعَ اللهَ ونثِقَ بهِ، وأن نُتقِنَ العملَ وندعوَ اللهَ أن يتقبَّلَهُ.'),
  ]),
  KidsStory(id: 'ilyas', category: StoryCategory.prophets, seconds: 74.92, bytes: 6472702, captions: [
    StoryCaption(0.25, 10.16, text: 'أكرمَ اللهُ عبدَهُ إلياسَ عليهِ السلامُ بالنبوّةِ والرسالةِ، وأرسلَهُ إلى قومِهِ من بني إسرائيلَ.'),
    StoryCaption(10.71, 15.29, text: 'وكانوا يعبدونَ صنمًا، ويترُكونَ عبادةَ اللهِ.'),
    StoryCaption(15.84, 20.53, text: 'فقالَ لهُم: اتَّقوا اللهَ وحدَهُ، ولا تُشرِكوا معهُ غيرَهُ.'),
    StoryCaption(21.08, 26.76, text: 'كيفَ تعبدونَ صنمًا، وتترُكونَ عبادةَ اللهِ أحسنِ الخالقينَ؟'),
    StoryCaption(27.31, 35.28, surah: 37, ayah: 125),
    StoryCaption(36.13, 41.99, text: 'اللهَ ربَّكُم الذي خلقَكُم، وخلقَ آباءَكُم من قبلِكُم.'),
    StoryCaption(42.54, 48.87, text: 'فكذَّبَهُ قومُهُ، إلّا عبادَ اللهِ الذينَ أخلصوا دينَهُم للهِ، فإنَّهُم ناجونَ.'),
    StoryCaption(49.42, 56.23, text: 'وجعلَ اللهُ لإلياسَ ذِكرًا جميلًا في الأممِ بعدَهُ، وسلامٌ من اللهِ عليهِ.'),
    StoryCaption(56.78, 64.47, text: 'وكذلكَ يجزي اللهُ المحسنينَ، فقد كانَ من عبادِهِ المؤمنينَ المخلصينَ.'),
    StoryCaption(65.02, 73.42, text: 'تعلَّمْنا من إلياسَ: أن نعبُدَ اللهَ الذي خلقَنا، وأن نقولَ الحقَّ ولو خالفَنا الناسُ.'),
  ]),
  KidsStory(id: 'kahf', category: StoryCategory.righteous, seconds: 140.67, bytes: 10789304, captions: [
    StoryCaption(0.25, 7.82, text: 'كانَ فِتيةٌ شُبّانٌ آمنوا بربِّهِم، فزادَهُمُ اللهُ هُدًى وثباتًا على الحقِّ.'),
    StoryCaption(8.37, 14.84, text: 'وكانَ قومُهُم يعبدونَ الأصنامَ، ويريدونَ أن يُرغِموهُم على عبادتِها.'),
    StoryCaption(15.39, 24.10, text: 'فقوّى اللهُ قلوبَهُم، فقاموا وقالوا: ربُّنا ربُّ السماواتِ والأرضِ، لن نعبُدَ غيرَهُ.'),
    StoryCaption(24.65, 31.38, text: 'ثمَّ تركوا قومَهُم، ولجؤوا إلى كهفٍ في الجبلِ ليعبُدوا ربَّهُم وحدَهُ.'),
    StoryCaption(31.93, 37.60, text: 'ودعَوْا ربَّهُم أن يرحمَهُم، ويُيسِّرَ لهُم طريقَ الصوابِ.'),
    StoryCaption(38.15, 55.78, surah: 18, ayah: 10),
    StoryCaption(56.63, 60.73, text: 'فألقى اللهُ عليهِمُ النومَ العميقَ في الكهفِ.'),
    StoryCaption(61.28, 69.41, text: 'وكانَتِ الشمسُ إذا طلعَتْ تميلُ عن كهفِهِم، وإذا غربَتْ تتركُهُم، فلا يؤذيهِم حرُّها.'),
    StoryCaption(69.96, 77.44, text: 'وكانَ اللهُ يُقلِّبُهُم وهم نائمونَ، مرّةً على الجنبِ الأيمنِ ومرّةً على الأيسرِ.'),
    StoryCaption(77.99, 83.36, text: 'وكلبُهُم الذي صاحبَهُم مادٌّ ذراعَيْهِ عندَ بابِ الكهفِ.'),
    StoryCaption(83.91, 87.87, text: 'وناموا ثلاثَمئةِ سنةٍ وتسعَ سنينَ.'),
    StoryCaption(88.42, 96.11, text: 'ثمَّ أيقظَهُمُ اللهُ كما كانوا، فسألَ بعضُهُم بعضًا: كم نِمْنا؟ قالوا: يومًا أو بعضَ يومٍ.'),
    StoryCaption(96.66, 100.50, text: 'وقالَ آخرونَ: ربُّكُم أعلمُ بما نِمتُم.'),
    StoryCaption(101.05, 113.09, text: 'فأرسلوا واحدًا منهُم بنقودِهِمُ الفضّيّةِ إلى المدينةِ، يشتري طعامًا حلالًا طيِّبًا، ويتلطَّفُ حتّى لا يعرِفَهُم أحدٌ.'),
    StoryCaption(113.64, 120.20, text: 'فلمّا رأى البائعُ نقودَهُمُ القديمةَ، انكشفَ أمرُهُم، وعرَفَ الناسُ قصَّتَهُم.'),
    StoryCaption(120.75, 129.90, text: 'فعلِمَ الناسُ أنَّ وعدَ اللهِ حقٌّ، وأنَّ اللهَ يبعثُ الناسَ بعدَ الموتِ، كما أيقظَ الفتيةَ بعدَ نومٍ طويلٍ.'),
    StoryCaption(130.45, 139.18, text: 'تعلَّمْنا من أصحابِ الكهفِ: أن نثبُتَ على الحقِّ ولو كانَ الناسُ حولَنا على غيرِهِ، وأنَّ مَن لجأَ إلى اللهِ حفِظَهُ.'),
  ]),
  KidsStory(id: 'luqman', category: StoryCategory.righteous, seconds: 108.53, bytes: 8630533, captions: [
    StoryCaption(0.25, 9.93, text: 'كانَ لقمانُ عبدًا صالحًا، أعطاهُ اللهُ الحكمةَ: الفقهَ في الدينِ، وسلامةَ العقلِ، والصوابَ في القولِ.'),
    StoryCaption(10.48, 16.41, text: 'وأمرَهُ اللهُ أن يشكُرَهُ على نِعَمِهِ، ومن يشكُرْ فإنَّما ينفعُ نفسَهُ.'),
    StoryCaption(16.96, 25.40, text: 'وجلسَ لقمانُ يَعِظُ ابنَهُ، فقالَ لهُ: يا بُنيَّ، لا تُشرِكْ باللهِ شيئًا، فالشركُ أعظمُ الذنوبِ.'),
    StoryCaption(25.95, 40.55, surah: 31, ayah: 13),
    StoryCaption(41.40, 51.73, text: 'وأمرَنا اللهُ أن نبَرَّ والدَيْنا ونُحسِنَ إليهِما؛ فقد حملَتْنا أمَّهاتُنا ضعفًا على ضعفٍ، وأرضعَتْنا عامَيْنِ.'),
    StoryCaption(52.28, 55.73, text: 'فنشكُرُ اللهَ، ثمَّ نشكُرُ والدَيْنا.'),
    StoryCaption(56.28, 67.50, text: 'وقالَ لقمانُ: يا بُنيَّ، لو كانَ العملُ صغيرًا مثلَ حبّةِ خردلٍ، في صخرةٍ أو في السماواتِ أو في الأرضِ، يأتي بهِ اللهُ.'),
    StoryCaption(68.05, 72.59, text: 'فاللهُ لطيفٌ بعبادِهِ، خبيرٌ بأعمالِهِم.'),
    StoryCaption(73.14, 81.48, text: 'يا بُنيَّ، أقِمِ الصلاةَ، وأْمُرْ بالخيرِ، وانْهَ عن الشرِّ بلُطفٍ ولِينٍ، واصبِرْ على ما يُصيبُكَ.'),
    StoryCaption(82.03, 91.58, text: 'ولا تُعرِضْ بوجهِكَ عن الناسِ إذا كلَّموكَ، ولا تمشِ في الأرضِ متكبِّرًا؛ فاللهُ لا يحبُّ المتكبِّرينَ.'),
    StoryCaption(92.13, 96.37, text: 'وتواضَعْ في مشيِكَ، واخفِضْ صوتَكَ ولا ترفعْهُ.'),
    StoryCaption(96.92, 107.04, text: 'تعلَّمْنا من لقمانَ: أن نعبُدَ اللهَ وحدَهُ، ونَبَرَّ آباءَنا وأمهاتِنا، ونصلّيَ، ونتواضعَ، ونتكلَّمَ بأدبٍ.'),
  ]),
  KidsStory(id: 'fil', category: StoryCategory.quran, seconds: 71.42, bytes: 5564780, captions: [
    StoryCaption(0.25, 7.94, text: 'جاءَ أبرهةُ الحبشيُّ بجيشٍ ومعهُ الفيلُ، يريدونَ أن يهدِموا الكعبةَ المباركةَ.'),
    StoryCaption(8.49, 11.98, text: 'لكنَّ اللهَ أبطلَ ما دبَّروهُ من الشرِّ.'),
    StoryCaption(12.53, 17.48, text: 'فأرسلَ اللهُ عليهِم طيرًا في جماعاتٍ متتابعةٍ.'),
    StoryCaption(18.03, 22.24, text: 'ترميهِم بحجارةٍ من طينٍ متحجِّرٍ.'),
    StoryCaption(22.79, 26.52, text: 'فصاروا كأوراقِ الزرعِ اليابسةِ.'),
    StoryCaption(27.07, 36.15, text: 'تعلَّمْنا من أصحابِ الفيلِ: أنَّ اللهَ قادرٌ، وأنَّهُ يُبطِلُ كيدَ الظالمينَ مهما كانوا أقوياءَ.'),
    StoryCaption(36.70, 44.04, surah: 105, ayah: 1),
    StoryCaption(44.44, 50.50, surah: 105, ayah: 2),
    StoryCaption(50.90, 57.04, surah: 105, ayah: 3),
    StoryCaption(57.44, 64.96, surah: 105, ayah: 4),
    StoryCaption(65.36, 70.82, surah: 105, ayah: 5),
  ]),
  KidsStory(id: 'yusuf', category: StoryCategory.prophets, seconds: 230.63, bytes: 17369228, captions: [
    StoryCaption(0.25, 9.97, text: 'رأى يوسفُ عليهِ السلامُ وهو صغيرٌ في منامِهِ: أحدَ عشرَ كوكبًا والشمسَ والقمرَ يسجدونَ لهُ.'),
    StoryCaption(10.52, 16.55, text: 'فقالَ لهُ أبوهُ يعقوبُ: يا بُنيَّ، لا تحكِ رؤياكَ لإخوتِكَ، فيحسُدوكَ.'),
    StoryCaption(17.10, 25.45, text: 'وكانَ إخوتُهُ يقولونَ: أبونا يحبُّ يوسفَ وأخاهُ أكثرَ منّا، فاتَّفَقوا أن يُبعِدوهُ عن أبيهِ.'),
    StoryCaption(26.00, 30.47, text: 'فأخذوهُ معهُم إلى المراعي، وألقَوْهُ في البئرِ.'),
    StoryCaption(31.02, 36.04, text: 'وأوحى اللهُ إلى يوسفَ: ستُخبِرُهُم يومًا بما فعلوا.'),
    StoryCaption(36.59, 45.19, text: 'ورجعوا إلى أبيهِم ليلًا يبكونَ، وقالوا: أكلَهُ الذئبُ، وجاؤوا بقميصِهِ عليهِ دمٌ كذِبٌ.'),
    StoryCaption(45.74, 55.57, text: 'فقالَ يعقوبُ: بل أنتُم دبَّرتُم أمرًا سيِّئًا، فسأصبرُ صبرًا لا أشكو فيهِ إلّا إلى اللهِ، وأستعينُ بهِ.'),
    StoryCaption(56.12, 62.91, text: 'ومرَّتْ قافلةٌ، فأرسلوا من يأتيهِم بالماءِ، فلمّا أدلى دلوَهُ تعلَّقَ بهِ يوسفُ.'),
    StoryCaption(63.46, 72.33, text: 'فباعوهُ بدراهمَ قليلةٍ، وذهبوا بهِ إلى مصرَ، فاشتراهُ العزيزُ، وقالَ لامرأتِهِ: أكرِمي مقامَهُ.'),
    StoryCaption(72.88, 80.15, text: 'ولمّا كبِرَ يوسفُ، أعطاهُ اللهُ فهمًا وعلمًا؛ لأنَّهُ كانَ من المحسنينَ.'),
    StoryCaption(80.70, 90.71, text: 'ثمَّ سُجِنَ يوسفُ ظلمًا وهو بريءٌ، وفي السجنِ دعا صاحبَيْهِ إلى عبادةِ اللهِ وحدَهُ، وفسَّرَ لهُما رؤياهُما.'),
    StoryCaption(91.26, 102.81, text: 'ورأى ملِكُ مصرَ في منامِهِ: سبعَ بقراتٍ سِمانٍ تأكلُهُنَّ سبعٌ نحيلاتٌ، وسبعَ سنبلاتٍ خُضرٍ وأُخَرَ يابساتٍ.'),
    StoryCaption(103.36, 114.74, text: 'ففسَّرَها يوسفُ: سبعُ سنينَ فيها خيرٌ كثيرٌ، فادَّخِروا الحبَّ في سنابلِهِ، ثمَّ سبعُ سنينَ شديدةٌ تأكلونَ فيها ما ادَّخرتُم.'),
    StoryCaption(115.29, 120.79, text: 'ثمَّ يأتي عامٌ ينزلُ فيهِ المطرُ، ويكثُرُ فيهِ الخيرُ.'),
    StoryCaption(121.34, 131.98, text: 'فلمّا ظهرَتْ براءتُهُ، أخرجَهُ الملكُ من السجنِ وقرَّبَهُ، فقالَ يوسفُ: اجعلْني على خزائنِ مصرَ، فإنّي أمينٌ عليمٌ.'),
    StoryCaption(132.53, 141.01, text: 'وجاءَتِ السنواتُ الشديدةُ، فجاءَ إخوتُهُ إلى مصرَ يطلبونَ الطعامَ، فعرَفَهُم ولم يعرِفوهُ.'),
    StoryCaption(141.56, 152.42, text: 'فأكرَمَهُم، وطلبَ منهُم أن يأتوا بأخيهِم من أبيهِم، فلمّا جاؤوا بهِ ضمَّهُ إليهِ، وقالَ لهُ سِرًّا: أنا أخوكَ، فلا تحزَنْ.'),
    StoryCaption(152.97, 165.16, text: 'ثمَّ كشفَ لإخوتِهِ أنَّهُ يوسفُ، وأنَّ هذا أخوهُ، وأنَّ اللهَ أكرمَهُما وجمعَ بينَهُما؛ فمَن خافَ اللهَ وصبرَ جزاهُ اللهُ على إحسانِهِ.'),
    StoryCaption(165.71, 170.74, text: 'فقالوا: لقد فضَّلَكَ اللهُ علينا، وقد كُنّا مخطئينَ.'),
    StoryCaption(171.29, 184.64, surah: 12, ayah: 92),
    StoryCaption(185.49, 191.71, text: 'وأرسلَ قميصَهُ إلى أبيهِ، فلمّا أُلقِيَ على وجهِهِ رجعَ إليهِ بصرُهُ.'),
    StoryCaption(192.26, 210.39, text: 'وجاءَ يعقوبُ وأهلُهُ إلى مصرَ، فأجلسَ يوسفُ أبوَيْهِ على سريرِهِ إكرامًا لهُما، وسجدَ لهُ أبواهُ وإخوتُهُ تحيّةً، لا عبادةً، وكانَ ذلكَ جائزًا في شريعتِهِم، وهو حرامٌ في شريعتِنا.'),
    StoryCaption(210.94, 218.53, text: 'فقالَ يوسفُ: يا أبي، هذا تفسيرُ الرؤيا التي رأيتُها وأنا صغيرٌ، وقد حقَّقَها ربّي.'),
    StoryCaption(219.08, 229.13, text: 'تعلَّمْنا من يوسفَ: أن نصبرَ ونتَّقيَ اللهَ، وأن نسامحَ مَن أساءَ إلينا، فاللهُ يجزي المحسنينَ على إحسانِهِم.'),
  ]),
  KidsStory(id: 'shuayb', category: StoryCategory.prophets, seconds: 105.83, bytes: 9255998, captions: [
    StoryCaption(0.25, 5.83, text: 'أرسلَ اللهُ إلى أهلِ مَديَنَ أخاهُم شُعيبًا عليهِ السلامُ.'),
    StoryCaption(6.38, 11.75, text: 'فقالَ لهُم: يا قومِ، اعبُدوا اللهَ وحدَهُ، ليسَ لكُم إلهٌ غيرُهُ.'),
    StoryCaption(12.30, 18.30, text: 'وكانوا يُنقِصونَ الكيلَ والميزانَ، فيأخذونَ من حقوقِ الناسِ في البيعِ.'),
    StoryCaption(18.85, 27.10, text: 'فقالَ لهُم: أتِمّوا الكيلَ والميزانَ بالعدلِ، ولا تُنقِصوا الناسَ حقَّهُم، ولا تُفسِدوا في الأرضِ.'),
    StoryCaption(27.65, 47.61, surah: 11, ayah: 85),
    StoryCaption(48.46, 55.31, text: 'وقالَ: ما يبقى لكُم من الربحِ الحلالِ خيرٌ لكُم من الكسبِ الحرامِ.'),
    StoryCaption(55.86, 65.30, text: 'فسخِروا منهُ وقالوا: هل صلاتُكَ تأمرُكَ أن نتركَ عبادةَ آبائِنا، وألّا نتصرَّفَ في أموالِنا كما نحبُّ؟'),
    StoryCaption(65.85, 75.51, text: 'فقالَ شعيبٌ: لا أريدُ إلّا أن أُصلِحَكُم بقدرِ طاقتي، ولا يُعينُني على ذلكَ إلّا اللهُ، وعليهِ أعتمدُ.'),
    StoryCaption(76.06, 79.73, text: 'وكانَ لا يأمرُهُم بشيءٍ ويفعلُ غيرَهُ.'),
    StoryCaption(80.28, 85.05, text: 'لكنَّهُم أصرّوا، وقالوا: لا نفهمُ كثيرًا ممّا تقولُ.'),
    StoryCaption(85.60, 93.92, text: 'فلمّا جاءَ أمرُ اللهِ، نجّى شعيبًا والذينَ آمنوا معهُ برحمتِهِ، وأخذَتِ الصيحةُ الظالمينَ.'),
    StoryCaption(94.47, 104.35, text: 'تعلَّمْنا من شعيبٍ: أن نكونَ أمناءَ في البيعِ والشراءِ، لا نغُشُّ ولا نأخذُ حقَّ أحدٍ، وأنَّ الحلالَ خيرٌ من الحرامِ.'),
  ]),
  KidsStory(id: 'musa_baby', category: StoryCategory.prophets, seconds: 113.66, bytes: 8892058, captions: [
    StoryCaption(0.25, 5.72, text: 'وُلِدَ موسى عليهِ السلامُ، وخافَتْ عليهِ أمُّهُ من فرعونَ.'),
    StoryCaption(6.27, 14.54, text: 'فألهمَها اللهُ: أرضِعيهِ مطمئنّةً، فإذا خِفتِ عليهِ فضعيهِ في صندوقٍ، وألقيهِ في النيلِ.'),
    StoryCaption(15.09, 21.20, text: 'ولا تخافي ولا تحزَني؛ فاللهُ سيرُدُّهُ إليكِ، ويجعلُهُ رسولًا.'),
    StoryCaption(21.75, 50.33, surah: 28, ayah: 7),
    StoryCaption(51.18, 57.09, text: 'فوضعَتْهُ في صندوقٍ وألقَتْهُ في النيلِ، وقالَتْ لأختِهِ: اتبَعي أثرَهُ.'),
    StoryCaption(57.64, 63.60, text: 'فتبِعَتْهُ أختُهُ، تنظُرُ إليهِ من بعيدٍ، وهم لا يعرفونَ أنَّها أختُهُ.'),
    StoryCaption(64.15, 67.65, text: 'فوجدَهُ أعوانُ فرعونَ وأخذوهُ.'),
    StoryCaption(68.20, 78.19, text: 'فلمّا رأتْهُ امرأةُ فرعونَ، ألقى اللهُ محبَّتَهُ في قلبِها، فقالَتْ: لا تقتُلوهُ، لعلَّنا نتَّخِذُهُ ولدًا.'),
    StoryCaption(78.74, 85.01, text: 'وأصبحَ قلبُ أمِّ موسى مشغولًا بهِ، فثبَّتَها اللهُ فصبرَتْ.'),
    StoryCaption(85.56, 89.69, text: 'وكانَ موسى لا يرضَعُ من أيِّ امرأةٍ أحضروها لهُ.'),
    StoryCaption(90.24, 97.19, text: 'فقالَتْ أختُهُ: أنا أعرفُ أهلَ بيتٍ يعتنونَ بهِ ويُرضِعونَهُ، ويُحسِنونَ إليهِ. فوافَقوا.'),
    StoryCaption(97.74, 106.05, text: 'فردَّهُ اللهُ إلى أمِّهِ؛ لتفرحَ بهِ ولا تحزنَ عليهِ، ولتعرفَ أنَّ اللهَ يَفي بما وعدَ.'),
    StoryCaption(106.60, 112.16, text: 'تعلَّمْنا من أمِّ موسى: أن نثِقَ بوعدِ اللهِ، فاللهُ لا يُخلِفُ وعدَهُ.'),
  ]),
  KidsStory(id: 'dayf', category: StoryCategory.prophets, seconds: 108.07, bytes: 7849391, captions: [
    StoryCaption(0.25, 9.46, text: 'جاءَ إلى إبراهيمَ عليهِ السلامُ ضيوفٌ غرباءُ، فقالوا: سلامًا، فردَّ عليهِم: سلامٌ.'),
    StoryCaption(10.01, 14.19, text: 'ولم يكُنْ يعرِفُ أنَّهُم ملائكةٌ كرامٌ.'),
    StoryCaption(14.74, 24.11, text: 'فذهبَ إلى أهلِهِ سريعًا، وجاءَهُم بعجلٍ سمينٍ مشويٍّ، وقرَّبَهُ إليهِم بلطفٍ: ألا تأكلونَ؟'),
    StoryCaption(24.66, 29.94, text: 'فلمّا رآهُم لا يأكلونَ، أحسَّ في نفسِهِ خوفًا منهُم.'),
    StoryCaption(30.49, 36.67, text: 'فقالوا: لا تخَفْ، نحنُ ملائكةُ اللهِ، أرسلَنا إلى قومِ لوطٍ.'),
    StoryCaption(37.22, 48.49, text: 'وكانَتِ امرأتُهُ سارةُ قائمةً وراءَ السِّترِ تسمعُ، فبشَّروها بولدٍ اسمُهُ إسحاقُ، ومن بعدِهِ حفيدٌ اسمُهُ يعقوبُ.'),
    StoryCaption(49.04, 55.50, text: 'فتعجَّبَتْ: كيفَ يكونُ لي ولدٌ وأنا عجوزٌ، وزوجي شيخٌ كبيرٌ؟'),
    StoryCaption(56.05, 61.79, text: 'فقالوا لها: لا تعجَبي من أمرِ اللهِ، فهو قادرٌ على كلِّ شيءٍ.'),
    StoryCaption(62.34, 84.07, surah: 11, ayah: 73),
    StoryCaption(84.92, 91.19, text: 'وقالوا: هكذا قالَ ربُّكِ، وهو القادرُ على ذلكَ، الحكيمُ العليمُ.'),
    StoryCaption(91.74, 97.15, text: 'وبشَّروا إبراهيمَ أنَّ هذا الولدَ سيكونُ من أهلِ العلمِ باللهِ.'),
    StoryCaption(97.70, 106.57, text: 'تعلَّمْنا من إبراهيمَ: أن نُكرِمَ الضيفَ، ونرُدَّ السلامَ بأحسنَ منهُ، وأنَّ اللهَ لا يُعجِزُهُ شيءٌ.'),
  ]),
  KidsStory(id: 'sabt', category: StoryCategory.quran, seconds: 99.03, bytes: 7585867, captions: [
    StoryCaption(0.25, 8.23, text: 'كانَتْ قريةٌ بقربِ البحرِ، أمرَ اللهُ أهلَها أن يُعظِّموا يومَ السبتِ، ولا يصيدوا فيهِ سمكًا.'),
    StoryCaption(8.78, 15.85, text: 'فاختبرَهُمُ اللهُ: كانَتِ الأسماكُ تأتيهِم يومَ السبتِ كثيرةً، طافيةً على وجهِ البحرِ.'),
    StoryCaption(16.40, 21.43, text: 'فإذا ذهبَ يومُ السبتِ، ذهبَتِ الأسماكُ، فلا يرَوْنَ منها شيئًا.'),
    StoryCaption(21.98, 28.13, text: 'فاحتالَ بعضُهُم: يحبِسونَ السمكَ يومَ السبتِ في حُفَرٍ، ويصطادونَهُ بعدَهُ.'),
    StoryCaption(28.68, 34.11, text: 'فقامَتْ جماعةٌ صالحةٌ تعِظُهُم وتنهاهُم عن معصيةِ اللهِ.'),
    StoryCaption(34.66, 42.25, text: 'فقالَتْ لهُم جماعةٌ ثالثةٌ: لماذا تنصحونَ قومًا سيُهلِكُهُمُ اللهُ؟'),
    StoryCaption(42.80, 50.74, text: 'فقالوا: نعِظُهُم لنؤدِّيَ ما أمرَنا اللهُ بهِ، ولعلَّهُم يتَّقونَ اللهَ ويتوبونَ.'),
    StoryCaption(51.29, 72.87, surah: 7, ayah: 164),
    StoryCaption(73.72, 81.48, text: 'فلمّا لم يسمعِ المعتدونَ النصيحةَ، أنجى اللهُ الذينَ كانوا ينهَوْنَ عن المعصيةِ.'),
    StoryCaption(82.03, 87.81, text: 'وعاقبَ المعتدينَ، فجعلَهُم قِرَدةً مُبعَدينَ عن كلِّ خيرٍ.'),
    StoryCaption(88.36, 97.55, text: 'تعلَّمْنا من أصحابِ السبتِ: ألّا نحتالَ على أمرِ اللهِ، وأن ننصحَ بلطفٍ، فالنصيحةُ تُنجّي صاحبَها.'),
  ]),
  KidsStory(id: 'ihya', category: StoryCategory.quran, seconds: 137.83, bytes: 8824385, captions: [
    StoryCaption(0.25, 8.96, text: 'مرَّ رجلٌ على قريةٍ تهدَّمَتْ بيوتُها، فقالَ: كيفَ يُحيي اللهُ هذهِ القريةَ بعدَ موتِها؟'),
    StoryCaption(9.51, 16.91, text: 'فأماتَهُ اللهُ مئةَ عامٍ، ثمَّ أحياهُ، وسألَهُ: كم لبثْتَ؟ قالَ: يومًا أو بعضَ يومٍ.'),
    StoryCaption(17.46, 26.74, text: 'فأخبرَهُ أنَّهُ لبثَ مئةَ عامٍ، وأمرَهُ أن ينظُرَ إلى طعامِهِ وشرابِهِ: لم يتغيَّرا طولَ هذهِ المدّةِ.'),
    StoryCaption(27.29, 32.57, text: 'وأن ينظُرَ إلى حمارِهِ، كيفَ يُحييهِ اللهُ بعدَ أن صارَ عظامًا.'),
    StoryCaption(33.12, 39.96, text: 'فلمّا رأى ذلكَ بعينِهِ، أيقنَ أنَّ اللهَ قادرٌ على كلِّ شيءٍ.'),
    StoryCaption(40.51, 49.49, text: 'وطلبَ إبراهيمُ عليهِ السلامُ من ربِّهِ أن يُرِيَهُ كيفَ يُحيي الموتى، ليزدادَ يقينًا على يقينِهِ.'),
    StoryCaption(50.04, 102.76, surah: 2, ayah: 260),
    StoryCaption(103.60, 112.16, text: 'فأمرَهُ اللهُ أن يأخذَ أربعةً من الطيرِ، ويجعلَ على كلِّ جبلٍ منها جزءًا، ثمَّ يناديَها.'),
    StoryCaption(112.71, 119.42, text: 'فنادى إبراهيمُ، فعادَ كلُّ جزءٍ إلى مكانِهِ، وجاءَتِ الطيرُ مسرعةً.'),
    StoryCaption(119.97, 124.80, text: 'فاللهُ عزيزٌ لا يغلِبُهُ شيءٌ، حكيمٌ في أفعالِهِ.'),
    StoryCaption(125.34, 136.32, text: 'تعلَّمْنا من الآيتَيْنِ: أنَّ اللهَ الذي خلقَنا أوَّلَ مرّةٍ قادرٌ على أن يُحيِيَنا بعدَ الموتِ، وأن نسألَ لنزدادَ يقينًا.'),
  ]),
  KidsStory(id: 'hudhud', category: StoryCategory.prophets, seconds: 125.90, bytes: 9647239, captions: [
    StoryCaption(0.25, 8.02, text: 'تفقَّدَ سليمانُ عليهِ السلامُ الطيرَ، فلم يجِدِ الهدهدَ، فقالَ: ما لي لا أرى الهدهدَ؟'),
    StoryCaption(8.57, 11.88, text: 'وأرادَ أن يعرِفَ عُذرَهُ في غيابِهِ.'),
    StoryCaption(12.43, 19.22, text: 'فجاءَ الهدهدُ بعدَ قليلٍ، وقالَ: جئتُكَ من سبأٍ في اليمنِ بخبرٍ يقينٍ.'),
    StoryCaption(19.77, 24.04, text: 'وجدتُ امرأةً تحكمُهُم، ولها عرشٌ عظيمٌ.'),
    StoryCaption(24.59, 30.32, text: 'ووجدتُها هي وقومَها يسجدونَ للشمسِ، ولا يعبدونَ اللهَ.'),
    StoryCaption(30.87, 38.30, text: 'فقالَ سليمانُ: سنعرفُ هل قلتَ الصدقَ أم لا، اذهبْ بكتابي هذا إليهِم.'),
    StoryCaption(38.85, 47.05, text: 'فألقى الهدهدُ الكتابَ إلى الملكةِ، فجمعَتْ أشرافَ قومِها وقالَتْ: وصلَني كتابٌ كريمٌ.'),
    StoryCaption(47.60, 58.05, surah: 27, ayah: 30),
    StoryCaption(58.90, 64.10, text: 'وكانَ فيهِ: ألّا تتكبَّروا، وأقبِلوا مسلمينَ للهِ.'),
    StoryCaption(64.65, 70.98, text: 'فاستشارَتْ قومَها، ثمَّ أرسلَتْ إلى سليمانَ هديّةً من نفائسِ الأموالِ.'),
    StoryCaption(71.53, 78.88, text: 'فقالَ سليمانُ: ما أعطاني اللهُ خيرٌ ممّا أعطاكُم، ولم يقبَلِ الهديّةَ.'),
    StoryCaption(79.43, 93.28, text: 'ثمَّ قالَ: أيُّكُم يأتيني بعرشِها؟ فقالَ رجلٌ أعطاهُ اللهُ علمًا: أنا آتيكَ بهِ قبلَ أن ترمَشَ عينُكَ. فدعا اللهَ، فجاءَ العرشُ.'),
    StoryCaption(93.83, 104.38, text: 'فلمّا رآهُ سليمانُ عندَهُ قالَ: هذا من نعمةِ اللهِ عليَّ، ليمتحنَني: هل أشكرُهُ على نعمتِهِ أم أجحدُها؟'),
    StoryCaption(104.93, 114.71, text: 'فلمّا جاءَتِ الملكةُ، رأَتْ قدرةَ اللهِ وصِدْقَ سليمانَ، فقالَتْ: أسلمْتُ معَ سليمانَ للهِ ربِّ العالمينَ.'),
    StoryCaption(115.26, 124.41, text: 'تعلَّمْنا من الهدهدِ: أن نقولَ الصدقَ، وأن ندعوَ إلى اللهِ. ومن سليمانَ: أن نشكُرَ اللهَ على كلِّ نعمةٍ.'),
  ]),
  KidsStory(id: 'adam', category: StoryCategory.prophets, seconds: 151.00, bytes: 10782893, captions: [
    StoryCaption(0.25, 9.35, text: 'قالَ اللهُ للملائكةِ: إنّي جاعلٌ في الأرضِ قومًا يَخلُفُ بعضُهُم بعضًا لعِمارتِها.'),
    StoryCaption(9.90, 18.22, text: 'فسألَتِ الملائكةُ عن الحكمةِ في ذلكَ، فأخبرَهُمُ اللهُ أنَّهُ يعلمُ ما لا يعلمونَ.'),
    StoryCaption(18.77, 29.97, text: 'وعلَّمَ اللهُ آدمَ أسماءَ الأشياءِ كلِّها، ثمَّ عرضَها على الملائكةِ، فقالوا: لا نعرفُ إلّا ما علَّمْتَنا يا ربَّنا.'),
    StoryCaption(30.52, 33.46, text: 'فأخبرَهُم آدمُ بأسمائِها.'),
    StoryCaption(34.01, 45.14, text: 'وأمرَ اللهُ الملائكةَ أن يسجُدوا لآدمَ تحيّةً وإكرامًا، فسجدوا كلُّهُم، إلّا إبليسَ أبى تكبُّرًا وحسدًا.'),
    StoryCaption(45.69, 59.70, text: 'وأسكنَ اللهُ آدمَ وزوجَهُ حوّاءَ الجنّةَ، وأباحَ لهُما أن يأكُلا من ثمارِها ما شاءا، إلّا شجرةً واحدةً نهاهُما عنها.'),
    StoryCaption(60.25, 67.28, text: 'وفيها لا تجوعُ ولا تعرى، ولا تعطشُ ولا يُصيبُكَ حرُّ الشمسِ.'),
    StoryCaption(67.83, 76.83, text: 'وحذَّرَهُ اللهُ: إنَّ إبليسَ عدوٌّ لكُما، فاحذَرا أن يكونَ سببًا في خروجِكُما من الجنّةِ.'),
    StoryCaption(77.38, 87.90, text: 'فوسوسَ لهُما الشيطانُ، وزعمَ أنَّ هذهِ الشجرةَ تجعلُهُما يعيشانِ أبدًا، وحلفَ إنّهُ لهُما ناصحٌ، وهو كاذبٌ.'),
    StoryCaption(88.45, 92.37, text: 'فأكلا من الشجرةِ، ونسِيَ آدمُ الوصيّةَ.'),
    StoryCaption(92.92, 102.06, text: 'فندِما، ودعَوا ربَّهُما معترفَيْنِ بذنبِهِما، يسألانِهِ أن يغفرَ لهُما ويرحمَهُما.'),
    StoryCaption(102.61, 118.07, surah: 7, ayah: 23),
    StoryCaption(118.92, 124.73, text: 'فتابَ اللهُ على آدمَ، وغفرَ لهُ؛ إنَّهُ هو التوّابُ الرحيمُ.'),
    StoryCaption(125.28, 128.75, text: 'ثمَّ اصطفاهُ اللهُ وقرَّبَهُ، وهداهُ.'),
    StoryCaption(129.30, 139.19, text: 'وأهبطَهُمُ اللهُ إلى الأرضِ، ووعدَهُم أن يأتيَهُم ما فيهِ هدايتُهُم، فمَن اتَّبعَهُ فلن يخافَ ولن يحزنَ.'),
    StoryCaption(139.74, 149.51, text: 'تعلَّمْنا من آدمَ: أنَّ الشيطانَ عدوٌّ لنا، وأنَّنا إذا أخطأْنا نرجعُ إلى اللهِ ونستغفرُهُ، فهو التوّابُ الرحيمُ.'),
  ]),
  KidsStory(id: 'isa', category: StoryCategory.prophets, seconds: 139.65, bytes: 9972048, captions: [
    StoryCaption(0.25, 6.24, text: 'كانَتْ مريمُ امرأةً صالحةً، اصطفاها اللهُ على نساءِ العالمينَ.'),
    StoryCaption(6.79, 13.09, text: 'وابتعدَتْ عن أهلِها إلى مكانٍ من جهةِ الشرقِ، وجعلَتْ دونَهُم سِترًا.'),
    StoryCaption(13.64, 18.62, text: 'فأرسلَ اللهُ إليها المَلَكَ جبريلَ، فاستعاذَتْ بالرحمنِ منهُ.'),
    StoryCaption(19.17, 25.34, text: 'فقالَ لها: إنّما أنا رسولُ ربِّكِ، جئتُ لأُبشِّرَكِ بغلامٍ طاهرٍ.'),
    StoryCaption(25.89, 36.80, text: 'فتعجَّبَتْ: كيفَ يكونُ لي ولدٌ ولستُ ذاتَ زوجٍ؟ فقالَ: ذلكَ سهلٌ على اللهِ، إذا أرادَ شيئًا قالَ لهُ: كُنْ، فيكونُ.'),
    StoryCaption(37.35, 44.25, text: 'فخلقَهُ اللهُ من غيرِ أبٍ؛ ليكونَ علامةً للناسِ على قدرةِ اللهِ، ورحمةً منهُ.'),
    StoryCaption(44.80, 52.81, text: 'وجاءَ وقتُ الولادةِ عندَ جذعِ نخلةٍ، فنُودِيَتْ: لا تحزَني، فقد أجرى اللهُ تحتَكِ جدولَ ماءٍ.'),
    StoryCaption(53.36, 60.97, text: 'وحرِّكي جذعَ النخلةِ، يتساقطْ عليكِ رُطَبٌ طازجٌ، فكُلي واشربي وطيبي نفسًا.'),
    StoryCaption(61.52, 67.22, text: 'ثمَّ أتَتْ قومَها تحمِلُهُ، فأنكروا ذلكَ عليها، فأشارَتْ إليهِ.'),
    StoryCaption(67.77, 73.73, text: 'فقالوا: كيفَ نكلِّمُ طفلًا رضيعًا في مهدِهِ؟ فتكلَّمَ عيسى وهو رضيعٌ.'),
    StoryCaption(74.28, 84.31, surah: 19, ayah: 30),
    StoryCaption(85.16, 94.58, text: 'وقالَ: جعلَني اللهُ مبارَكًا أينما كنتُ، وأوصاني بالصلاةِ والزكاةِ، وجعلَني بارًّا بأمّي.'),
    StoryCaption(95.13, 101.50, text: 'ولمّا كبِرَ، أرسلَهُ اللهُ إلى بني إسرائيلَ، وعلَّمَهُ التوراةَ والإنجيلَ.'),
    StoryCaption(102.05, 111.24, text: 'وأعطاهُ اللهُ معجزاتٍ: يصنعُ من الطينِ شكلَ طيرٍ، فينفُخُ فيهِ، فيصيرُ طيرًا بإذنِ اللهِ.'),
    StoryCaption(111.79, 119.63, text: 'ويشفي مَن وُلِدَ أعمى، ومَن بهِ بَرَصٌ، ويُحيي الموتى بإذنِ اللهِ.'),
    StoryCaption(120.18, 128.02, text: 'وكلُّ ذلكَ دليلٌ على أنَّهُ نبيُّ اللهِ ورسولُهُ، وأنَّهُ عبدُ اللهِ.'),
    StoryCaption(128.57, 138.15, text: 'تعلَّمْنا من عيسى وأمِّهِ: أنَّ اللهَ قادرٌ على كلِّ شيءٍ، وأن نَبَرَّ أمَّهاتِنا ونحافظَ على الصلاةِ.'),
  ]),
  KidsStory(id: 'dhulqarnayn', category: StoryCategory.righteous, seconds: 130.43, bytes: 9069183, captions: [
    StoryCaption(0.25, 11.07, text: 'كانَ ذو القرنينِ ملِكًا صالحًا، مكَّنَ اللهُ لهُ في الأرضِ، وأعطاهُ من كلِّ شيءٍ أسبابًا وطُرُقًا.'),
    StoryCaption(11.62, 15.32, text: 'فأخذَ بتلكَ الأسبابِ بجِدٍّ واجتهادٍ.'),
    StoryCaption(15.87, 26.93, text: 'فسارَ حتّى وصلَ إلى مغربِ الشمسِ، فرآها كأنَّها تغرُبُ في عينٍ حارّةٍ ذاتِ طينٍ أسودَ، ووجدَ هناكَ قومًا.'),
    StoryCaption(27.48, 33.99, text: 'فحكمَ فيهِم بالعدلِ: مَن آمنَ وعمِلَ صالحًا أحسنَ إليهِ، ولانَ لهُ في القولِ.'),
    StoryCaption(34.54, 44.43, text: 'ثمَّ سارَ إلى المشرقِ، فوجدَ الشمسَ تطلُعُ على قومٍ ليسَ لهُم بناءٌ يستُرُهُم، ولا شجرٌ يُظِلُّهُم.'),
    StoryCaption(44.98, 52.42, text: 'ثمَّ سارَ حتّى وصلَ بينَ جبلَيْنِ، فوجدَ قومًا لا يكادونَ يفهمونَ كلامَ غيرِهِم.'),
    StoryCaption(52.97, 62.04, text: 'فقالوا: إنَّ يأجوجَ ومأجوجَ يُفسِدونَ في الأرضِ، فهل نجمعُ لكَ مالًا، وتجعلُ بينَنا وبينَهُم حاجزًا؟'),
    StoryCaption(62.59, 70.23, text: 'فقالَ: ما أعطاني ربّي خيرٌ من مالِكُم، ولكنْ أعينوني بقوّتِكُم.'),
    StoryCaption(70.78, 76.84, text: 'فجاؤوا بقِطَعِ الحديدِ، ووضعوها بينَ الجبلَيْنِ حتّى ساوَتْهُما.'),
    StoryCaption(77.39, 84.00, text: 'فأشعلوا النارَ حتّى صارَ الحديدُ كلُّهُ نارًا، ثمَّ صبَّ عليهِ النحاسَ.'),
    StoryCaption(84.55, 92.02, text: 'فصارَ سدًّا عاليًا أملسَ، لم يستطيعوا أن يصعدوا فوقَهُ، ولا أن يَثقُبوهُ.'),
    StoryCaption(92.57, 99.39, text: 'فلم يتكبَّرْ ذو القرنينِ، بل قالَ: هذا السدُّ من رحمةِ اللهِ بالناسِ.'),
    StoryCaption(99.94, 118.15, surah: 18, ayah: 98),
    StoryCaption(119.00, 128.95, text: 'تعلَّمْنا من ذي القرنينِ: أن نأخذَ بالأسبابِ ونجتهدَ، وأن نعدِلَ، وأن ننسُبَ الفضلَ للهِ لا لأنفسِنا.'),
  ]),
  KidsStory(id: 'jannatayn', category: StoryCategory.quran, seconds: 139.80, bytes: 16427304, captions: [
    StoryCaption(0.25, 8.94, text: 'هذا مثلٌ ذكرَهُ اللهُ لنا عن رجلَيْنِ: أحدُهُما مؤمنٌ، والآخرُ كافرٌ.'),
    StoryCaption(9.49, 18.93, text: 'وكانَ للكافرِ حديقتانِ من العنبِ، حولَهُما نخلٌ كثيرٌ، وبينَهُما زروعٌ.'),
    StoryCaption(19.48, 29.09, text: 'وأثمرَتْ كلُّ حديقةٍ ثمرَها كاملًا، ويجري بينَهُما نهرٌ يسقيهِما.'),
    StoryCaption(29.64, 39.94, text: 'فامتلأَ صاحبُ الحديقتَيْنِ غرورًا، وقالَ لصاحبِهِ المؤمنِ: أنا أكثرُ منكَ مالًا، وأقوى أعوانًا.'),
    StoryCaption(40.49, 50.49, text: 'ودخلَ حديقتَهُ، فأعجبَتْهُ ثمارُها، وقالَ: ما أظنُّ أنَّ هذهِ الحديقةَ تهلِكُ أبدًا.'),
    StoryCaption(51.04, 54.39, text: 'وقالَ: وما أظنُّ أنَّ القيامةَ آتيةٌ.'),
    StoryCaption(54.94, 63.89, text: 'فقالَ لهُ صاحبُهُ المؤمنُ يعِظُهُ: كيفَ تكفُرُ باللهِ الذي خلقَكَ من ترابٍ، ثمَّ جعلَكَ إنسانًا سويًّا؟'),
    StoryCaption(64.44, 71.12, text: 'أمّا أنا فأقولُ: اللهُ ربّي وحدَهُ، ولا أُشرِكُ بهِ أحدًا.'),
    StoryCaption(71.67, 80.00, text: 'وهلّا ذكرتَ اللهَ وشكرتَهُ حينَ دخلتَ حديقتَكَ فأعجبَتْكَ، فهي من فضلِهِ لا من قوّتِكَ.'),
    StoryCaption(80.55, 101.84, surah: 18, ayah: 39),
    StoryCaption(102.69, 108.42, text: 'فتحقَّقَ ما حذَّرَهُ منهُ صاحبُهُ، وهلكَ كلُّ ما في الحديقةِ.'),
    StoryCaption(108.97, 118.83, text: 'فصارَ يُقلِّبُ كفَّيْهِ ندمًا على ما أنفقَ فيها، ويتمنّى لو أنَّهُ عبدَ اللهَ وحدَهُ ولم يُشرِكْ بهِ.'),
    StoryCaption(119.38, 124.85, text: 'ولم يجِدْ مَن ينصُرُهُ من الذينَ كانَ يفتخِرُ بهِم.'),
    StoryCaption(125.40, 138.30, text: 'تعلَّمْنا من صاحبِ الجنَّتَيْنِ: أن نشكُرَ اللهَ على نِعَمِهِ ولا نغترَّ، وأن نذكُرَ اللهَ إذا أعجبَنا شيءٌ، كما سمِعْنا في الآيةِ.'),
  ]),
  KidsStory(id: 'dawud', category: StoryCategory.prophets, seconds: 140.07, bytes: 10566404, captions: [
    StoryCaption(0.25, 10.64, text: 'بعدَ زمانِ موسى، طلبَ بنو إسرائيلَ من نبيِّهِم أن يجعلَ لهُم ملِكًا، يقاتلونَ معهُ أعداءَهُم الذينَ أخرجوهُم من ديارِهِم.'),
    StoryCaption(11.19, 16.12, text: 'فأخبرَهُم نبيُّهُم أنَّ اللهَ اختارَ طالوتَ ملِكًا عليهِم.'),
    StoryCaption(16.67, 25.82, text: 'فقالوا: كيفَ يكونُ ملِكًا وليسَ عندَهُ مالٌ كثيرٌ؟ فقالَ: إنَّ اللهَ اختارَهُ، وزادَهُ علمًا وقوّةً.'),
    StoryCaption(26.37, 38.99, text: 'فخرجَ طالوتُ بجنودِهِ، وقالَ لهُم: إنَّ اللهَ سيختبرُكُم بنهرٍ، ومَن يشربْ منهُ لا يكونُ من أصحابي، إلّا مَن أخذَ ملءَ كفِّهِ فقط.'),
    StoryCaption(39.54, 46.28, text: 'فلمّا وصلوا إلى النهرِ شربَ أكثرُهُم، إلّا قليلًا صبروا على العطشِ.'),
    StoryCaption(46.83, 53.24, text: 'وعبرَ طالوتُ معَ القلّةِ المؤمنةِ، فرأَوا جالوتَ وجنودَهُ الكثيرينَ.'),
    StoryCaption(53.79, 65.84, text: 'فقالَ المؤمنونَ: كثيرًا ما غلبَتْ جماعةٌ قليلةٌ صابرةٌ جماعةً كبيرةً، بعونِ اللهِ وتوفيقِهِ، فاللهُ يُعينُ الصابرينَ.'),
    StoryCaption(66.39, 75.51, text: 'ودعَوا ربَّهُم: أن يُنزِلَ على قلوبِهِم صبرًا، ويُثبِّتَ أقدامَهُم، وينصُرَهُم.'),
    StoryCaption(76.06, 99.15, surah: 2, ayah: 250),
    StoryCaption(100.00, 106.26, text: 'فنصرَهُمُ اللهُ على عدوِّهِم، وقتلَ داودُ عليهِ السلامُ جالوتَ.'),
    StoryCaption(106.81, 113.52, text: 'وأعطى اللهُ داودَ بعدَ ذلكَ الملكَ والنبوّةَ، وعلَّمَهُ ممّا يشاءُ.'),
    StoryCaption(114.07, 118.98, text: 'وكانَتِ الجبالُ والطيرُ تُسبِّحُ معَهُ إذا سبَّحَ.'),
    StoryCaption(119.53, 128.32, text: 'وألانَ اللهُ لهُ الحديدَ، فكانَ كالعجينِ، يصنعُ منهُ دروعًا تحمي لابسَها.'),
    StoryCaption(128.87, 138.58, text: 'تعلَّمْنا من داودَ وأصحابِ طالوتَ: أنَّ النصرَ من عندِ اللهِ، وأنَّ اللهَ يُعينُ الصابرينَ.'),
  ]),
  KidsStory(id: 'dhabih', category: StoryCategory.prophets, seconds: 110.78, bytes: 7832135, captions: [
    StoryCaption(0.25, 6.13, text: 'دعا إبراهيمُ عليهِ السلامُ ربَّهُ: يا ربِّ، أعطِني ولدًا صالحًا.'),
    StoryCaption(6.68, 12.04, text: 'فاستجابَ اللهُ لهُ، وبشَّرَهُ بغلامٍ حليمٍ، هو إسماعيلُ.'),
    StoryCaption(12.59, 21.05, text: 'فلمّا كبِرَ إسماعيلُ وصارَ يمشي معَ أبيهِ، قالَ لهُ أبوهُ: إنّي رأيتُ في المنامِ أنّي أذبحُكَ، فما رأيُكَ؟'),
    StoryCaption(21.60, 26.07, text: 'ورؤيا الأنبياءِ حقٌّ، وأمرٌ من اللهِ.'),
    StoryCaption(26.62, 34.24, text: 'فقالَ إسماعيلُ بارًّا بأبيهِ: يا أبي، افعلْ ما أمرَكَ اللهُ بهِ، وسأصبرُ بإذنِ اللهِ.'),
    StoryCaption(34.79, 43.57, text: 'فلمّا استسلما لأمرِ اللهِ، ناداهُ اللهُ: يا إبراهيمُ، قد صدَّقْتَ الرؤيا، وفعلْتَ ما أُمِرْتَ بهِ.'),
    StoryCaption(44.12, 49.61, text: 'إنَّ هذا كانَ اختبارًا عظيمًا، ظهرَ فيهِ صِدقُ إيمانِهِ.'),
    StoryCaption(50.16, 56.34, text: 'فأنقذَ اللهُ إسماعيلَ، وجعلَ بدلًا منهُ كبشًا عظيمًا.'),
    StoryCaption(56.89, 61.51, surah: 37, ayah: 107),
    StoryCaption(62.36, 67.97, text: 'وكذلكَ يجزي اللهُ المحسنينَ، فيُنجّيهِم من الشدائدِ.'),
    StoryCaption(68.52, 75.96, text: 'وأبقى اللهُ لإبراهيمَ ذِكرًا حسنًا في الأممِ بعدَهُ، وسلامٌ على إبراهيمَ.'),
    StoryCaption(76.51, 85.41, text: 'ثمَّ بشَّرَهُ اللهُ بولدِهِ إسحاقَ نبيًّا من الصالحينَ، جزاءً على صبرِهِ، وباركَ عليهِما.'),
    StoryCaption(85.96, 95.04, text: 'وكانَ ذلكَ الكبشُ قُربانًا وسُنّةً إلى يومِ القيامةِ؛ ولذلكَ نُضحّي في عيدِ الأضحى.'),
    StoryCaption(95.59, 109.28, text: 'تعلَّمْنا من إبراهيمَ وإسماعيلَ: أن نُطيعَ اللهَ ونَبَرَّ آباءَنا، وأنَّ مَن صبرَ على أمرِ اللهِ جعلَ اللهُ لهُ فرَجًا.'),
  ]),
  KidsStory(id: 'khidr', category: StoryCategory.prophets, seconds: 190.22, bytes: 13609156, captions: [
    StoryCaption(0.25, 12.15, text: 'خرجَ موسى عليهِ السلامُ معَ خادمِهِ يوشعَ بنِ نونٍ، يريدُ أن يلقى عبدًا صالحًا، ليتعلَّمَ منهُ علمًا ليسَ عندَهُ.'),
    StoryCaption(12.70, 24.60, text: 'وكانَ معَهُما حوتٌ ميِّتٌ زادًا لهُما، فلمّا جلسا عندَ صخرةٍ عندَ ملتقى البحرَيْنِ، صارَ الحوتُ حيًّا، ونزلَ إلى البحرِ.'),
    StoryCaption(25.15, 37.34, text: 'فلمّا ابتعدا وجاعا، تذكَّرَ الخادمُ الحوتَ، فقالَ موسى: هذا ما كنّا نطلبُ؛ فهو علامةُ مكانِ العبدِ الصالحِ. فرجعا إلى الصخرةِ.'),
    StoryCaption(37.89, 48.02, text: 'فوجدا هناكَ الخضرَ عليهِ السلامُ، وقد آتاهُ اللهُ رحمةً من عندِهِ، وعلَّمَهُ علمًا عظيمًا.'),
    StoryCaption(48.57, 53.59, text: 'فسلَّمَ عليهِ موسى، وقالَ: أتأذنُ لي أن أتبعَكَ لتُعلِّمَني؟'),
    StoryCaption(54.14, 60.95, text: 'قالَ الخضرُ: إنَّكَ لن تصبرَ على ما ترى منّي، فكيفَ تصبرُ على أمورٍ لا تعرفُ حكمتَها؟'),
    StoryCaption(61.50, 65.91, text: 'فقالَ موسى: سأصبرُ إن شاءَ اللهُ، ولن أعصيَ لكَ أمرًا.'),
    StoryCaption(66.46, 79.10, surah: 18, ayah: 69),
    StoryCaption(79.95, 95.68, text: 'قالَ الخضرُ: فلا تسألْني عن شيءٍ حتّى أُبيِّنَهُ لكَ. فانطلقا، فركبا سفينةً حملَهُما أهلُها بلا أجرٍ، فخرقَها الخضرُ بنزعِ لوحٍ منها.'),
    StoryCaption(96.23, 106.67, text: 'فقالَ موسى: أخرقْتَها لتُغرِقَ أهلَها؟ فذكَّرَهُ الخضرُ بشرطِهِ، فاعتذرَ موسى، وطلبَ منهُ أن يُسامحَهُ لأنَّهُ نسيَ.'),
    StoryCaption(107.22, 114.32, text: 'ثمَّ رأى موسى أمرًا آخرَ أشدَّ فأنكرَهُ، ثمَّ قالَ: إن سألتُكَ بعدَها فلا تصاحِبْني.'),
    StoryCaption(114.87, 127.74, text: 'فأتيا قريةً، فطلبا طعامًا فلم يُضيِّفوهُما، ووجدا جدارًا مائلًا يوشكُ أن يسقطَ، فأقامَهُ الخضرُ حتّى استوى.'),
    StoryCaption(128.29, 140.12, text: 'فقالَ موسى: لو شئتَ لأخذْتَ عليهِ أجرًا نشتري بهِ طعامًا. فقالَ الخضرُ: هنا نفترقُ، وسأُخبِرُكَ بحكمةِ ما لم تصبِرْ عليهِ.'),
    StoryCaption(140.67, 152.27, text: 'أمّا السفينةُ فكانَتْ لمساكينَ يعملونَ في البحرِ، وكانَ أمامَهُم ملِكٌ يأخذُ كلَّ سفينةٍ سليمةٍ غصبًا، فعِبْتُها لتسلَمَ لهُم.'),
    StoryCaption(152.82, 167.26, text: 'وأمّا الجدارُ فكانَ لطفلَيْنِ يتيمَيْنِ، وتحتَهُ مالٌ مدفونٌ لهُما، وكانَ أبوهُما رجلًا صالحًا، فأرادَ اللهُ أن يكبَرا ثمَّ يُخرِجا مالَهُما، رحمةً منهُ بهِما.'),
    StoryCaption(167.81, 173.75, text: 'وما فعلْتُ شيئًا من ذلكَ من عندِ نفسي، وإنّما فعلْتُهُ بأمرِ اللهِ.'),
    StoryCaption(174.30, 188.72, text: 'تعلَّمْنا من موسى والخضرِ: أن نطلُبَ العلمَ ونتواضعَ لهُ، وأنَّ وراءَ ما لا نفهمُهُ حكمةً يعلمُها اللهُ، وأنَّ صلاحَ الآباءِ ينفعُ الأبناءَ.'),
  ]),
];
